// Only the listener and Kafka: OrderService is a mock, so no database is needed.
@SpringBootTest(
        classes = {PaymentSettledListener.class, PaymentSettledErrorHandling.class},
        properties = "spring.kafka.bootstrap-servers=${spring.embedded.kafka.brokers}")
@ImportAutoConfiguration({KafkaAutoConfiguration.class, JacksonAutoConfiguration.class})
@EmbeddedKafka(partitions = 1, topics = {"payment-settled", "payment-settled.DLT"})
class PaymentSettledListenerTest {

    @Autowired
    KafkaTemplate<String, String> kafka;

    @Autowired
    EmbeddedKafkaBroker broker;

    @MockitoBean
    OrderService orders;

    @Test
    void retriesATransientFailureWithBackoffThenDeadLetters() {
        String orderId = unique();
        List<Long> attempts = new CopyOnWriteArrayList<>();
        doAnswer(invocation -> {
            attempts.add(System.nanoTime());
            throw new QueryTimeoutException("database busy");
        }).when(orders).markPaid(forOrder(orderId));
        String message = payment(orderId);

        long sentAt = System.nanoTime();
        kafka.send("payment-settled", orderId, message);
        ConsumerRecord<String, String> dead = awaitDeadLetter(message);
        long deadLetteredAt = System.nanoTime();

        assertThat(dead.value()).isEqualTo(message);
        // Nothing more after the dead letter.
        verify(orders, after(1_000).times(4)).markPaid(forOrder(orderId));
        assertThat(attempts).hasSize(4);
        for (int i = 1; i < attempts.size(); i++) {
            assertThat(Duration.ofNanos(attempts.get(i) - attempts.get(i - 1)))
                    .isGreaterThanOrEqualTo(Duration.ofMillis(100));
        }
        assertThat(Duration.ofNanos(deadLetteredAt - sentAt))
                .isLessThan(Duration.ofSeconds(5));
    }

    @Test
    void aTransientFailureThatClearsIsNotDeadLettered() {
        String orderId = unique();
        AtomicInteger calls = new AtomicInteger();
        doAnswer(invocation -> {
            if (calls.incrementAndGet() == 1) {
                throw new QueryTimeoutException("database busy");
            }
            return null;
        }).when(orders).markPaid(forOrder(orderId));
        String message = payment(orderId);

        kafka.send("payment-settled", orderId, message);

        verify(orders, timeout(5_000).times(2)).markPaid(forOrder(orderId));
        verify(orders, after(1_000).times(2)).markPaid(forOrder(orderId));
        assertThat(deadLetters()).extracting(ConsumerRecord::value).doesNotContain(message);
    }

    @Test
    void deadLettersInvalidJsonWithoutRetrying() {
        String message = "not json " + unique();

        kafka.send("payment-settled", message);

        assertThat(awaitDeadLetter(message).value()).isEqualTo(message);
        verify(orders, never()).markPaid(any());
    }

    @Test
    void deadLettersJsonThatIsNotAPaymentWithoutRetrying() {
        String message = "{\"orderId\": \"" + unique() + "\", \"amount\": \"lots\"}";

        kafka.send("payment-settled", message);

        assertThat(awaitDeadLetter(message).value()).isEqualTo(message);
        verify(orders, never()).markPaid(any());
    }

    @Test
    void deadLettersAPaymentForAMissingOrderWithoutRetrying() {
        String orderId = unique();
        doThrow(new OrderNotFoundException(orderId))
                .when(orders).markPaid(forOrder(orderId));
        String message = payment(orderId);

        kafka.send("payment-settled", orderId, message);

        assertThat(awaitDeadLetter(message).value()).isEqualTo(message);
        verify(orders, after(1_000).times(1)).markPaid(forOrder(orderId));
    }

    @Test
    void carriesOnWithTheNextRecordAfterADeadLetter() {
        String missing = unique();
        String next = unique();
        doThrow(new OrderNotFoundException(missing))
                .when(orders).markPaid(forOrder(missing));
        doNothing().when(orders).markPaid(forOrder(next));

        kafka.send("payment-settled", missing, payment(missing));
        kafka.send("payment-settled", next, payment(next));

        awaitDeadLetter(payment(missing));
        verify(orders, timeout(5_000)).markPaid(new PaymentSettled(next, "pay-" + next, 1_000));
    }

    private static String unique() {
        return String.valueOf(Math.abs(UUID.randomUUID().getMostSignificantBits()));
    }

    private static String payment(String orderId) {
        return "{\"orderId\":\"" + orderId + "\",\"paymentId\":\"pay-" + orderId
                + "\",\"amount\":1000}";
    }

    private static PaymentSettled forOrder(String orderId) {
        return argThat(event -> event != null && orderId.equals(event.orderId()));
    }

    private ConsumerRecord<String, String> awaitDeadLetter(String value) {
        List<ConsumerRecord<String, String>> found = new ArrayList<>();
        await().atMost(Duration.ofSeconds(10)).until(() -> {
            deadLetters().stream().filter(r -> value.equals(r.value()))
                    .findFirst().ifPresent(found::add);
            return !found.isEmpty();
        });
        return found.getFirst();
    }

    // Everything on the DLT so far, read by a fresh consumer group.
    private List<ConsumerRecord<String, String>> deadLetters() {
        Map<String, Object> props = KafkaTestUtils.consumerProps(broker, unique(), false);
        props.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, "earliest");
        try (Consumer<String, String> consumer = new DefaultKafkaConsumerFactory<>(props,
                new StringDeserializer(), new StringDeserializer()).createConsumer()) {
            broker.consumeFromAnEmbeddedTopic(consumer, PaymentSettledErrorHandling.DEAD_LETTER_TOPIC);
            List<ConsumerRecord<String, String>> records = new ArrayList<>();
            KafkaTestUtils.getRecords(consumer, Duration.ofMillis(500))
                    .forEach(records::add);
            return records;
        }
    }
}
