        verify(orders, after(1_000).times(4)).markPaid(forOrder(orderId));
        assertThat(attempts).hasSize(4);
        for (int i = 1; i < attempts.size(); i++) {
            assertThat(Duration.ofNanos(attempts.get(i) - attempts.get(i - 1)))
                    .isGreaterThanOrEqualTo(Duration.ofMillis(100));
        }
        assertThat(Duration.ofNanos(deadLetteredAt - sentAt))
                .isLessThan(Duration.ofSeconds(5));
    }

    @Test
    void aTransientFailureThatClearsIsNotDeadLettered() {
        String orderId = unique();
        AtomicInteger calls = new AtomicInteger();
        doAnswer(invocation -> {
