    void deadLettersJsonThatIsNotAPaymentWithoutRetrying() {
        String message = "{\"orderId\": \"" + unique() + "\", \"amount\": \"lots\"}";

        kafka.send("payment-settled", message);

        assertThat(awaitDeadLetter(message).value()).isEqualTo(message);
        verify(orders, never()).markPaid(any());
    }

    @Test
    void deadLettersAPaymentForAMissingOrderWithoutRetrying() {
        String orderId = unique();
        doThrow(new OrderNotFoundException(orderId))
                .when(orders).markPaid(forOrder(orderId));
        String message = payment(orderId);

        kafka.send("payment-settled", orderId, message);

        assertThat(awaitDeadLetter(message).value()).isEqualTo(message);
        verify(orders, after(1_000).times(1)).markPaid(forOrder(orderId));
    }

