        kafka.send("payment-settled", missing, payment(missing));
        kafka.send("payment-settled", next, payment(next));

        awaitDeadLetter(payment(missing));
        verify(orders, timeout(5_000)).markPaid(new PaymentSettled(next, "pay-" + next, 1_000));
    }

    private static String unique() {
