        return "{\"orderId\":\"" + orderId + "\",\"paymentId\":\"pay-" + orderId
                + "\",\"amount\":1000}";
    }

    private static PaymentSettled forOrder(String orderId) {
        return argThat(event -> event != null && orderId.equals(event.orderId()));
    }

    private ConsumerRecord<String, String> awaitDeadLetter(String value) {
        return await().atMost(Duration.ofSeconds(10))
                .until(() -> deadLetters.received.stream()
                                .filter(r -> value.equals(r.value())).findFirst(),
                        Optional::isPresent)
                .get();
    }

