        final List<ConsumerRecord<String, String>> received = new CopyOnWriteArrayList<>();

        @KafkaListener(topics = PaymentSettledErrorHandling.DEAD_LETTER_TOPIC,
                groupId = "dlt-test", properties = "auto.offset.reset=earliest")
        void on(ConsumerRecord<String, String> record) {
            received.add(record);
        }
    }
