package dev.example.orders;

import org.apache.kafka.common.TopicPartition;
import org.springframework.boot.kafka.autoconfigure.ConcurrentKafkaListenerContainerFactoryConfigurer;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.kafka.config.ConcurrentKafkaListenerContainerFactory;
import org.springframework.kafka.core.ConsumerFactory;
import org.springframework.kafka.core.KafkaOperations;
import org.springframework.kafka.listener.DeadLetterPublishingRecoverer;
import org.springframework.kafka.listener.DefaultErrorHandler;
import org.springframework.kafka.support.ExponentialBackOffWithMaxRetries;
import tools.jackson.core.JacksonException;

// Error handling for the payment-settled consumer. A failing record is retried
// with a backoff, 4 attempts in total over 250 + 500 + 1000 ms, then published
// to payment-settled.DLT with its original value, and the consumer moves on.
// Records that can never succeed skip the retries and go to the DLT at once.
@Configuration
public class PaymentSettledErrorHandling {

    public static final String DEAD_LETTER_TOPIC = "payment-settled.DLT";

    // A factory of its own so the error handler applies to this listener only.
    // The handler is not a bean: Spring Boot would put it on the default factory.
    @Bean
    public ConcurrentKafkaListenerContainerFactory<Object, Object> paymentSettledContainerFactory(
            ConcurrentKafkaListenerContainerFactoryConfigurer configurer,
            ConsumerFactory<Object, Object> consumerFactory,
            KafkaOperations<Object, Object> kafka) {
        ConcurrentKafkaListenerContainerFactory<Object, Object> factory =
                new ConcurrentKafkaListenerContainerFactory<>();
        configurer.configure(factory, consumerFactory);
        factory.setCommonErrorHandler(errorHandler(kafka));
        return factory;
    }

    static DefaultErrorHandler errorHandler(KafkaOperations<Object, Object> kafka) {
        // Partition -1 lets the producer choose, so the DLT does not need as many
        // partitions as the source topic.
        DeadLetterPublishingRecoverer recoverer = new DeadLetterPublishingRecoverer(
                kafka, (record, e) -> new TopicPartition(DEAD_LETTER_TOPIC, -1));
        ExponentialBackOffWithMaxRetries backOff = new ExponentialBackOffWithMaxRetries(3);
        backOff.setInitialInterval(250);
        backOff.setMultiplier(2);
        DefaultErrorHandler handler = new DefaultErrorHandler(recoverer, backOff);
        handler.addNotRetryableExceptions(JacksonException.class,
                OrderNotFoundException.class);
        return handler;
    }
}
